from typing import List

class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n, m = len(nums), len(changeIndices)

        def can(t: int) -> bool:
            last = [-1] * n
            for s in range(t):
                last[changeIndices[s] - 1] = s

            for i in range(n):
                if last[i] == -1:
                    return False

            available = 0
            for s in range(t):
                idx = changeIndices[s] - 1
                if last[idx] == s:
                    if available < nums[idx]:
                        return False
                    available -= nums[idx]
                else:
                    available += 1

            return True

        left, right = 1, m
        ans = -1

        while left <= right:
            mid = (left + right) // 2
            if can(mid):
                ans = mid
                right = mid - 1
            else:
                left = mid + 1

        return ans
```

